function GetWin {$p=Get-Process SmartLedger.App -ErrorAction SilentlyContinue|Select-Object -First 1;if(!$p){return $null};$p.Refresh();if(!$p.MainWindowHandle){return $null};try{return [System.Windows.Automation.AutomationElement]::FromHandle($p.MainWindowHandle)}catch{return $null}}
function Els {$w=GetWin;if(!$w){return @()};try{$a=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$z=@();foreach($e in $a){$z+=,$e};$z+=,$w;return $z}catch{return @()}}
function FindId([string]$id){foreach($e in (Els)){try{if($e.Current.AutomationId -eq $id -and !$e.Current.IsOffscreen){return $e}}catch{}};return $null}
function InvokeId([string]$id){$e=FindId $id;if(!$e){Log "MISSING_ID $id";return $false};try{$e.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern).Invoke();Log "INVOKED $id";return $true}catch{try{$e.GetCurrentPattern([System.Windows.Automation.LegacyIAccessiblePattern]::Pattern).DoDefaultAction();Log "INVOKED_DEFAULT $id";return $true}catch{Log "INVOKE_FAILED $id";return $false}}}
function Shot([string]$file){Start-Sleep -Milliseconds 800;$b=[System.Windows.Forms.Screen]::PrimaryScreen.Bounds;$bmp=New-Object System.Drawing.Bitmap($b.Width,$b.Height);$g=[System.Drawing.Graphics]::FromImage($bmp);$g.CopyFromScreen($b.Left,$b.Top,0,0,$b.Size);$path=Join-Path $shots $file;$bmp.Save($path,[System.Drawing.Imaging.ImageFormat]::Png);$g.Dispose();$bmp.Dispose();Log "CAPTURED $file $($b.Width)x$($b.Height) bytes=$((Get-Item $path).Length)"}
function WaitId([string]$id){for($i=0;$i -lt 20;$i++){Start-Sleep -Milliseconds 250;$e=FindId $id;if($e){return $e}};return $null}
function Nav([string]$id){if(!(InvokeId $id)){throw "Navigation failed: $id"};Start-Sleep -Milliseconds 650}
