if(InvokeId 'Btn_OpenNewBookDialog'){$e=WaitId 'Btn_CloseBookDialog';if($e){Shot '04-ledger-book-dialog-OPEN.png';$results.Add('Book dialog: visible close control; screenshot captured');InvokeId 'Btn_CloseBookDialog'|Out-Null}else{$results.Add('Book dialog: OPEN assertion FAILED')}}else{$results.Add('Book dialog: trigger failed')}
