Nav 'NavBtn_Expenses';if(InvokeId 'Btn_OpenNewExpenseDialog'){$e=WaitId 'Btn_CloseExpenseDialog';if($e){Shot '03-expense-entry-dialog-OPEN.png';$results.Add('Expense dialog: visible close control; screenshot captured');InvokeId 'Btn_CloseExpenseDialog'|Out-Null}else{$results.Add('Expense dialog: OPEN assertion FAILED; close control absent')}}else{$results.Add('Expense dialog: trigger failed')}
Nav 'NavBtn_Sales';if(InvokeId 'Btn_OpenNewSaleInvoice'){$barcode=WaitId 'SaleBarcodeInput';if($barcode){try{$barcode.SetFocus();Shot '05-invoice-line-entry-OPEN.png';$results.Add('Sales invoice dialog: barcode field visible and focused; screenshot captured')}catch{$results.Add('Sales invoice dialog: barcode focus failed')}}else{$results.Add('Sales invoice dialog: barcode field not visible after trigger')}}else{$results.Add('Sales invoice trigger failed')}
$xaml=[IO.File]::ReadAllText((Join-Path $root 'src\SmartLedger.App\Views\ModuleTemplates.xaml'));$remaining=[regex]::Matches($xaml,'<(?:TextBox|ComboBox|DatePicker)\b[^>]*\sHeight="(?:42|44|46)"').Count
$shotLines=@();foreach($f in (Get-ChildItem $shots -Filter '*-OPEN.png' -ErrorAction SilentlyContinue)){ $im=[System.Drawing.Image]::FromFile($f.FullName);$shotLines+=('- '+$f.Name+' — '+$im.Width+'x'+$im.Height+', '+$f.Length+' bytes');$im.Dispose() }
$reportLines=@('# SmartLedger Pro - Live Input Dialog Verification',"Date: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')","Workspace: $root",'', '## Build and regression gate','- Build: PASS - 0 warnings, 0 errors.','- Tests: PASS - 105 passed, 0 failed, 0 skipped.',"- Local input height overrides 42/44/46 in ModuleTemplates.xaml: $remaining.",'- Opening balance: FlowDirection LeftToRight; TextAlignment Right.','- BackupService.cs was not edited by this mission.','', '## Live walkthrough results',($results -join '; '),'','## Screenshot evidence',($shotLines -join [Environment]::NewLine),'','## Verification limits','Each open-dialog claim is based on the dedicated close control being found in the visible UI Automation tree. The sales entry claim is based on the barcode field being found and focused. This is a runtime visibility check, not a full manual sign-off of every watermark, label, and baseline.');$report=$reportLines -join [Environment]::NewLine
